    # ---- brand_kit_form.html ----
    ("brand_kit.page_title", "Brend kit", "Брендбук", "Brand kit"),
    ("brand_kit.h1", "Brend kit", "Брендбук", "Brand kit"),
    ("brand_kit.subtitle", "Logotip va brend ranglari -- Kreativ studiya AI yaratgan har bir reklama rasmiga logotipingizni aniq (fayl sifatida, AI chizmaydi) qo'yadi va ranglaringizni fon uslubida hisobga oladi. Ixtiyoriy: logotipsiz ham rasm yaratiladi, shunchaki logotip qatlami bo'sh qoladi.", "Логотип и фирменные цвета -- Креативная студия точно накладывает ваш логотип (как файл, AI его не рисует) на каждое созданное AI рекламное изображение и учитывает ваши цвета в стиле фона. Необязательно: изображение создаётся и без логотипа, просто слой логотипа остаётся пустым.", "Logo and brand colors -- the Creative studio places your logo precisely (as a file, AI doesn't draw it) onto every AI-generated ad image and factors your colors into the background style. Optional: an image is still generated without a logo, the logo layer is simply left empty."),
    ("brand_kit.back", "Orqaga", "Назад", "Back"),
    ("brand_kit.field_logo", "Logotip", "Логотип", "Logo"),
    ("brand_kit.logo_not_uploaded", "Logotip yuklanmagan", "Логотип не загружен", "Logo not uploaded"),
    ("brand_kit.logo_note", "PNG (shaffof fon -- tavsiya etiladi), JPG yoki WEBP, 8 MB gacha. Yangi fayl eskisini almashtiradi.", "PNG (прозрачный фон -- рекомендуется), JPG или WEBP, до 8 МБ. Новый файл заменяет старый.", "PNG (transparent background recommended), JPG or WEBP, up to 8 MB. A new file replaces the old one."),
    ("brand_kit.field_primary_color", "Asosiy rang", "Основной цвет", "Primary color"),
    ("brand_kit.field_secondary_color", "Ikkinchi rang", "Дополнительный цвет", "Secondary color"),
