    # ---- business_profile.question_* (business_profile.BUSINESS_PROFILE_QUESTIONS) ----
    ("business_profile.question_product_or_service_label", "Nima soting yoki qanday xizmat ko'rsatasiz?", "Что вы продаёте или какие услуги оказываете?", "What do you sell, or what service do you provide?"),
    ("business_profile.question_product_or_service_placeholder", "Masalan: erkaklar oyoq kiyimi, 30 dan ortiq model, o'rtacha narxda", "Например: мужская обувь, более 30 моделей, средний ценовой сегмент", "E.g.: men's footwear, 30+ models, mid-range price"),
    ("business_profile.question_product_or_service_helper", "AI reklama matni va javoblarni shu mahsulot/xizmatga moslab yozadi -- qancha aniqroq yozsangiz, shuncha aniqroq javob beradi.", "AI будет писать рекламные тексты и ответы под этот товар/услугу -- чем точнее вы напишете, тем точнее будет ответ.", "AI will write ad copy and answers tailored to this product/service -- the more precisely you write, the more precise its answers will be."),
    ("business_profile.question_target_audience_label", "Mijozlaringiz odatda kimlar (yosh, jins, hudud)?", "Кто обычно ваши клиенты (возраст, пол, регион)?", "Who are your customers usually (age, gender, region)?"),
    ("business_profile.question_target_audience_placeholder", "Masalan: 20-40 yosh, ko'proq ayollar, Toshkent shahri", "Например: 20-40 лет, преимущественно женщины, город Ташкент", "E.g.: age 20-40, mostly women, Tashkent city"),
    ("business_profile.question_target_audience_helper", "Reklama auditoriyasini va murojaat ohangini shu mijoz portretiga qarab tanlashga yordam beradi.", "Помогает подбирать рекламную аудиторию и тон обращения на основе этого портрета клиента.", "Helps choose the ad audience and the tone of voice based on this customer profile."),
    ("business_profile.question_sku_count_label", "Nechta xil mahsulot turi (SKU/model)ingiz bor?", "Сколько у вас разных видов товара (SKU/моделей)?", "How many different product types (SKUs/models) do you have?"),
    ("business_profile.question_sku_count_placeholder", "Masalan: 45 ta model, yoki \"1 ta xizmat turi\"", "Например: 45 моделей, или «1 вид услуги»", "E.g.: 45 models, or \"1 type of service\""),
    ("business_profile.question_sku_count_helper", "Assortiment kattaligi -- keng assortimentda AI umumiy reklama g'oyalarini, tor assortimentda esa aniq mahsulot bo'yicha chuqur tahlilni taklif qiladi.", "Размер ассортимента -- при широком ассортименте AI предлагает общие рекламные идеи, при узком -- глубокий анализ по конкретному товару.", "Assortment size -- with a wide range, AI suggests general ad ideas; with a narrow one, it offers deep analysis for a specific product."),
    ("business_profile.question_price_range_label", "O'rtacha chek/narx oralig'ingiz qancha?", "Какой у вас средний чек/ценовой диапазон?", "What's your average price / price range?"),
    ("business_profile.question_price_range_placeholder", "Masalan: 150 000 - 500 000 so'm", "Например: 150 000 - 500 000 сум", "E.g.: 150,000 - 500,000 UZS"),
    ("business_profile.question_price_range_helper", "Narx segmentini bilish AI'ga byudjet/ROI tahlilida va reklama uslubini (ekonom yoki premium) tanlashda yordam beradi.", "Знание ценового сегмента помогает AI в анализе бюджета/ROI и в выборе стиля рекламы (эконом или премиум).", "Knowing the price segment helps AI with budget/ROI analysis and choosing the ad style (economy or premium)."),
    ("business_profile.question_best_seller_label", "Eng ko'p sotiladigan yoki so'raladigan mahsulot/xizmatingiz qaysi?", "Какой ваш самый продаваемый или востребованный товар/услуга?", "What's your best-selling or most-requested product/service?"),
    ("business_profile.question_best_seller_placeholder", "Masalan: klassik model, u eng ko'p buyurtma qilinadi", "Например: классическая модель, её заказывают чаще всего", "E.g.: the classic model, it's ordered most often"),
    ("business_profile.question_best_seller_helper", "Yangi reklama g'oyalari va nimani ko'proq targetga qo'yish kerakligi bo'yicha maslahatlar shu javob asosida beriladi.", "На основе этого ответа даются советы по новым рекламным идеям и по тому, что стоит продвигать активнее.", "New ad ideas and advice on what to promote more are given based on this answer."),
    ("business_profile.question_competitors_label", "Asosiy raqobatchilaringiz kimlar (bilsangiz)?", "Кто ваши основные конкуренты (если знаете)?", "Who are your main competitors (if you know)?"),
    ("business_profile.question_competitors_placeholder", "Masalan: shahardagi 2-3 ta do'kon nomi yoki brend", "Например: 2-3 названия магазинов или брендов в городе", "E.g.: 2-3 store or brand names in your city"),
    ("business_profile.question_competitors_helper", "AI sizni raqobatchilardan ajratib turadigan afzalliklarni topib, reklama matnida shu farqni ta'kidlashga harakat qiladi.", "AI старается найти преимущества, выделяющие вас среди конкурентов, и подчеркнуть это отличие в рекламном тексте.", "AI tries to find advantages that set you apart from competitors and highlight that difference in ad copy."),
    ("business_profile.question_extra_notes_label", "AI yana nimani bilishi kerak (aksiya, afzallik, o'ziga xos jihat)?", "Что ещё должен знать AI (акции, преимущества, особенности)?", "What else should AI know (promotions, advantages, unique features)?"),
    ("business_profile.question_extra_notes_placeholder", "Masalan: bepul yetkazib berish, 1 yillik kafolat", "Например: бесплатная доставка, гарантия 1 год", "E.g.: free delivery, 1-year warranty"),
    ("business_profile.question_extra_notes_helper", "Yuqoridagi savollarga sig'magan, lekin mijozga muhim bo'lgan har qanday qo'shimcha ma'lumot -- shu yerga yozing.", "Любая дополнительная информация, не вошедшая в вопросы выше, но важная для клиента -- напишите здесь.", "Any extra information that doesn't fit the questions above but matters to the customer -- write it here."),

